const c = $input.item.json.choices?.[0]?.message?.content || '{}';
let idea; try{ idea=JSON.parse(c);}catch(e){ const m=c.match(/\{[\s\S]*\}/); idea=m?JSON.parse(m[0]):{}; }
if(!idea.slug) idea.slug=(idea.title||'product').toLowerCase().replace(/[^a-z0-9]+/g,'-').slice(0,60);
return [{ json: { ...idea } }];

