const base=$('IF Approved? Gate >=7').item.json;
const guide=$items('Groq Guide',0,0)[0]?.json?.choices?.[0]?.message?.content||'# Guide';
const checklist=$items('Groq Checklist',0,0)[0]?.json?.choices?.[0]?.message?.content||'# Checklist';
const svg=`<svg width='1600' height='1200' viewBox='0 0 1600 1200' xmlns='http://www.w3.org/2000/svg'><defs><linearGradient id='bg' x1='0' y1='0' x2='1' y2='1'><stop offset='0%' stop-color='#0f172a'/><stop offset='100%' stop-color='#6366f1'/></linearGradient></defs><rect width='1600' height='1200' fill='url(#bg)' rx='40'/><text x='80' y='150' font-family='Inter' font-weight='800' font-size='60' fill='white'>${(base.brand_name||'Premium').slice(0,30)}</text><foreignObject x='80' y='250' width='1400' height='500'><div xmlns='http://www.w3.org/1999/xhtml' style='font-family:Inter;color:white;font-size:48px;font-weight:800'>${(base.title||'').slice(0,120)}</div></foreignObject></svg>`;
const files={
  'User_Guide.md': guide,
  'Bonus_Checklist.md': checklist,
  'README.md': `# ${base.brand_name}\n${base.title}\nOutcome: ${base.dream_outcome}`,
  'Cover.svg': svg,
  'Cover.html': `<html><body style='margin:0'>${svg}</body></html>`,
  'gumroad.md': `# ${base.title}\n\nOutcome: ${base.dream_outcome}\nAvatar: ${base.avatar}\nPrice: $${base.suggested_price}`,
  'seo.txt': `Slug: ${base.slug} Title: ${base.title}`,
  'twitter.txt': `Launch ${base.brand_name}: ${base.title} Price $${base.suggested_price}`
};
return Object.entries(files).map(([fn, content])=>({ json: { slug: base.slug, filename: fn, content, brand_name: base.brand_name } }));
